        if input_type == 'switch':
            result[key] = result[key][0] if isinstance(result[key], list) else result[key]
            result[key] = not result[key]
        elif input_type == 'date':
            value = result[key]
            try:
                result[key] = datetime.strptime(value, '%Y-%m-%d').date() if value else value
            except ValueError:
                pass
    return result

