import os
import urllib.parse

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    if not os.path.isfile(urls_file):
        raise FileNotFoundError(f'The file {urls_file} does not exist.')
    with open(urls_file) as file:
        for line in file:
            url = line.strip()
            if not url:
                continue
            parsed_url = urllib.parse.urlparse(url)
            if not all([parsed_url.scheme, parsed_url.netloc]):
                raise ValueError(f'Invalid URL: {url}')
            collect_from_url(url, archive_dir=archive_dir, notes=notes)

import arrow

def chunk_date_range(self, start_date: Union[int, str, datetime], end_date: Union[int, str, datetime], chunk_size: int, chunk_unit: Optional[str]='months', date_format: Optional[str]=None) -> Tuple[Union[datetime, str], Union[datetime, str]]:
    relative_delta_settings = {chunk_unit: +chunk_size}
    if isinstance(start_date, (int, str)):
        start_date = self.any_to_datetime(start_date)
    if isinstance(end_date, (int, str)):
        end_date = self.any_to_datetime(end_date)
    sd = start_date
    ed = min(end_date, start_date + relativedelta(**relative_delta_settings))
    while 1:
        sdf = arrow.get(sd).format(date_format) if date_format else sd
        edf = arrow.get(ed).format(date_format) if date_format else ed
        yield (sdf, edf)
        if ed >= end_date:
            break
        sd = ed
        ed = min(end_date, sd + relativedelta(**relative_delta_settings))

def extend_substation_overloading(network, critical_stations):
    try:
        standard_transformer = network.equipment_data['mv_trafos'].loc[network.config['grid_expansion_standard_equipment']['hv_mv_transformer']]
    except KeyError:
        print('Standard HV/MV transformer is not in equipment list.')
    load_factor = network.config['grid_expansion_load_factors']['mv_feedin_case_transformer']
    feed_in_factor = network.config['grid_expansion_load_factors']['mv_load_case_transformer']
    transformers_changes = {'added': {}, 'removed': {}}
    for station in critical_stations:
        s_max_per_trafo = [_.type.S_nom for _ in station.transformers]
        s_station_pfa = critical_stations[station]
        s_trafo_missing = s_station_pfa - sum(s_max_per_trafo) * load_factor
        if max(s_max_per_trafo) >= s_trafo_missing:
            duplicated_transformer = min([_ for _ in station.transformers if _.type.S_nom > s_trafo_missing], key=lambda j: j.type.S_nom - s_trafo_missing)
            new_transformer = Transformer(id='MVStation_{}_transformer_{}'.format(str(station.id), str(len(station.transformers) + 1)), geom=duplicated_transformer.geom, grid=duplicated_transformer.grid, voltage_op=duplicated_transformer.voltage_op, type=copy.deepcopy(duplicated_transformer.type))
            station.add_transformer(new_transformer)
            transformers_changes['added'][station] = [new_transformer]
        else:
            station_transformer = station.transformers[0]
            number_transformers = math.ceil(s_station_pfa / (standard_transformer.S_nom * feed_in_factor))
            new_transformers = []
            for i in range(number_transformers):
                new_transformer = Transformer(id='MVStation_{}_transformer_{}'.format(str(station.id), str(i + 1)), geom=station_transformer.geom, grid=station_transformer.grid, voltage_op=station_transformer.voltage_op, type=copy.deepcopy(standard_transformer))
                new_transformers.append(new_transformer)
            transformers_changes['added'][station] = new_transformers
            transformers_changes['removed'][station] = station.transformers
            station.transformers = new_transformers
    if transformers_changes['added']:
        logger.debug('==> MV station has been reinforced due to overloading issues.')
    return transformers_changes

