def append(self, relpath, f, mode=None):
    abspath = self._abspath(relpath)
    fp = None
    try:
        try:
            fp = open(abspath, 'ab')
            if mode is not None:
                current_mode = stat.S_IMODE(os.lstat(abspath).st_mode)
                if current_mode != mode:
                    os.chmod(abspath, mode)
        except (IOError, OSError) as e:
            self._translate_error(e, relpath)
        fp.seek(0, 2)
        result = fp.tell()
        self._pump(f, fp)
    finally:
        if fp is not None:
            fp.close()
    return result

