def topics_for(products, parent=False):
    statsd.incr('wiki.facets.topics_for.db')
    docs = Document.objects.filter(locale=settings.WIKI_DEFAULT_LANGUAGE, is_archived=False, current_revision__isnull=False, category__in=settings.IA_DEFAULT_CATEGORIES)
    for product in products:
        docs = docs.filter(products=product)
    qs = Topic.objects
    qs = qs.filter(visible=True, document__in=docs).annotate(num_docs=Count('document')).distinct()
    if parent or parent is None:
        qs = qs.filter(parent=parent)
    return qs

def dump_json_output(output, output_path, json_style='pretty'):
    fp = resolve_output_path(output_path)
    highlit = json_style == 'pretty' and fp == sys.stdout and fp.isatty()
    json_encoder = ExtendedJsonEncoder(**JSON_PARAMS[json_style])
    for chunk in json_encoder.iterencode(output):
        if highlit:
            chunk = highlight_json(chunk)
        fp.write(chunk)
    fp.write('\n')

def encode_message(message):
    return bytes(message)

def test_hello_passes_routing_metadata(fake_socket_pair):
    address = ('127.0.0.1', 7687)
    sockets = fake_socket_pair(address)
    message = [0, 3, 177, 112, 160, 0, 0]
    sockets.server.sendall(encode_message(message))
    connection = Bolt4x2(address, sockets.client, PoolConfig.max_connection_lifetime, routing_context={'foo': 'bar'})
    connection.hello()
    (tag, fields) = sockets.server.pop_message()
    assert tag == 1
    assert len(fields) == 1
    assert fields[0]['routing'] == {'foo': 'bar'}

def replace(var, wrapper, message):
    if wrapper.source not in channels.Main.users:
        wrapper.pm(messages['invalid_channel'].format(channels.Main))
        return
    var = wrapper.game_state
    if var is None:
        return
    pl = get_players(var)
    if wrapper.source in pl:
        wrapper.pm(messages['you_already_playing'])
        return
    if not wrapper.source.account:
        wrapper.pm(messages['not_logged_in'])
        return
    participants = get_participants(var)
    target: Optional[User] = None
    for user in var.ALL_PLAYERS:
        if users.equals(user.account, wrapper.source.account):
            if user is wrapper.source or user not in participants:
                continue
            elif target is None:
                target = user
            else:
                wrapper.pm(messages['swap_notice'].format(botconfig.CMD_CHAR))
                return
    if target is None:
        wrapper.pm(messages['account_not_playing'])
        return
    if message:
        rest = message.split()
        (target, _) = users.complete_match(rest[0], participants)
        if target is None:
            wrapper.pm(messages['target_not_playing'])
            return
        if target not in participants:
            wrapper.pm(messages['target_no_longer_playing' if target.nick in var.DEAD else 'target_not_playing'])
            return
        if target.account is None:
            wrapper.pm(messages['target_not_logged_in'])
            return
    if users.equals(target.account, wrapper.source.account) and target is not wrapper.source:
        rename_player(var, wrapper.source, target.nick)
        target.swap(wrapper.source)
        if var.PHASE in var.GAME_PHASES:
            return_to_village(var, target, show_message=False)
        if not var.DEVOICE_DURING_NIGHT or var.PHASE != 'night':
            channels.Main.mode(('-v', target), ('+v', wrapper.source))
        channels.Main.send(messages['player_swap'].format(wrapper.source, target))
        if var.PHASE in var.GAME_PHASES:
            myrole.func(var, wrapper, '')

