def where(condition, x=None, y=None, /):
    missing = (x is None, y is None).count(True)
    if missing == 1:
        raise ValueError("Must provide both 'x' and 'y' or neither.")
    elif missing == 2:
        return dpnp.nonzero(condition)
    elif missing == 0:
        (usm_type, queue) = get_usm_allocations([condition, x, y])
        c_desc = dpnp.get_dpnp_descriptor(condition, copy_when_strides=False, copy_when_nondefault_queue=False, alloc_usm_type=usm_type, alloc_queue=queue)
        x_desc = dpnp.get_dpnp_descriptor(x, copy_when_strides=False, copy_when_nondefault_queue=False, alloc_usm_type=usm_type, alloc_queue=queue)
        y_desc = dpnp.get_dpnp_descriptor(y, copy_when_strides=False, copy_when_nondefault_queue=False, alloc_usm_type=usm_type, alloc_queue=queue)
        if c_desc and x_desc and y_desc:
            if c_desc.dtype != dpnp.bool:
                raise TypeError('condition must be a boolean array')
            return dpnp_where(c_desc, x_desc, y_desc).get_pyobj()
    return call_origin(numpy.where, condition, x, y)

def _unwrapunits(self, obj, units=None):
    if obj is None:
        return None
    if units is True:
        return (obj.getValue(), obj.getUnit())
    elif isinstance(units, str):
        unitClass = obj.getUnit().__class__
        if hasattr(unitClass, units):
            unitEnum = getattr(unitClass, units)
            obj = obj.__class__(obj, unitEnum)
        return obj
    else:
        return obj.getValue()

from concurrent.futures import ThreadPoolExecutor

def predict_on_structure_par(self):
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(self._predict_single_atom, n) for n in range(self.structure.nat)]
        for future in futures:
            future.result()
    self.structure.dft_forces = False

def _predict_single_atom(self, n):
    chemenv = ChemicalEnvironment(self.structure, n)
    for i in range(3):
        (force, var) = self.gp.predict(chemenv, i + 1)
        self.structure.forces[n][i] = float(force)
        self.structure.stds[n][i] = np.sqrt(np.absolute(var))

def update_agent_core_memory(self, user_id: uuid.UUID, agent_id: uuid.UUID, new_memory_contents: dict) -> dict:
    if self.ms.get_user(user_id=user_id) is None:
        raise ValueError(f'User user_id={user_id} does not exist')
    memgpt_agent = self._get_or_load_agent(user_id=user_id, agent_id=agent_id)
    old_core_memory = self.get_agent_memory(user_id=user_id, agent_id=agent_id)['core_memory']
    new_core_memory = old_core_memory.copy()
    modified = False
    if 'persona' in new_memory_contents and new_memory_contents['persona'] is not None:
        new_persona = new_memory_contents['persona']
        if old_core_memory['persona'] != new_persona:
            new_core_memory['persona'] = new_persona
            memgpt_agent.memory.edit_persona(new_persona)
            modified = True
    if 'human' in new_memory_contents and new_memory_contents['human'] is not None:
        new_human = new_memory_contents['human']
        if old_core_memory['human'] != new_human:
            new_core_memory['human'] = new_human
            memgpt_agent.memory.edit_human(new_human)
            modified = True
    if modified:
        memgpt_agent.rebuild_memory()
    return {'old_core_memory': old_core_memory, 'new_core_memory': new_core_memory, 'modified': modified}

