def level_check(self):
    if self.happiness > SETTLER.HAPPINESS_LEVEL_UP_REQUIREMENT:
        if self._upgrade_production is not None:
            storage = self.get_component(StorageComponent).inventory
            consumed_resources = self._upgrade_production.get_consumed_resources()
            if all((storage[res] >= abs(amount) for (res, amount) in consumed_resources.items())):
                for (res, amount) in consumed_resources.items():
                    storage.alter(res, -abs(amount))
                self.level_up()
                self._changed()
            else:
                return
        else:
            self.level_up()
            self._changed()
    elif self.happiness < SETTLER.HAPPINESS_LEVEL_DOWN_LIMIT:
        self.level_down()
        self._changed()

def prepare_form(form_request):
    form_data = {}
    form_data['user_agent'] = request.headers.get('User-Agent')
    form_data['src'] = request.args.get('src')
    form_data['extra_labels'] = request.args.getlist('label')
    form_data['url'] = request.args.get('url')
    if form_request.method == 'POST':
        json_data = form_request.get_json()
        form_data.update(json_data)
    channel = ''
    details = form_data.get('details')
    if details:
        channel = details.get('channel')
    if channel == 'release':
        return {'redirect': '/some-other-url', 'data': form_data}
    return form_data

