        self.root.update_idletasks()

async def get_backup_details(request):
    backup_id = request.match_info.get('backup_id', None)
    if not backup_id:
        raise web.HTTPBadRequest(reason='Backup id is required')
    try:
        backup_id = int(backup_id)
    except ValueError:
        raise web.HTTPBadRequest(reason='Invalid backup id')
    try:
        backup = Backup(connect.get_storage_async())
        backup_json = await backup.get_backup_details(backup_id)
        resp = {'status': _get_status(int(backup_json['status'])), 'id': backup_json['id'], 'date': backup_json['ts']}
    except exceptions.DoesNotExist:
        raise web.HTTPNotFound(reason='Backup id {} does not exist'.format(backup_id))
    except Exception as ex:
        raise web.HTTPInternalServerError(reason=str(ex))
    return web.json_response(resp)

def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if '(' in val and ')' in val:
        macro_key = val.strip()
        return cls.process_macro_keycode(macro_key)
    if '(' not in val and val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    return 0

@classmethod
def process_macro_keycode(cls, macro_key):
    return 0

def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if '(' not in val and val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    if '(' in val and val.endswith(')'):
        base_keycode = val[:val.index('(')]
        params = val[val.index('(') + 1:-1]
        if base_keycode in cls.qmk_id_to_keycode:
            return cls.qmk_id_to_keycode[base_keycode].code
    return 0

def _render_student_view_for_items(self, context, display_items, fragment, view=STUDENT_VIEW):
    render_items = not context.get('exclude_units', False)
    is_user_authenticated = self.is_user_authenticated(context)
    completion_service = self.runtime.service(self, 'completion')
    try:
        bookmarks_service = self.runtime.service(self, 'bookmarks')
    except NoSuchServiceError:
        bookmarks_service = None
    user = self.runtime.service(self, 'user').get_current_user()
    context['username'] = user.opt_attrs.get('edx-platform.username')
    display_names = [self.get_parent().display_name_with_default, self.display_name_with_default]
    contents = []
    for item in display_items:
        item_type = self._determine_item_type(item)
        usage_id = item.scope_ids.usage_id
        show_bookmark_button = False
        is_bookmarked = False
        if is_user_authenticated and bookmarks_service:
            show_bookmark_button = True
            is_bookmarked = bookmarks_service.is_bookmarked(usage_key=usage_id)
        context['show_bookmark_button'] = show_bookmark_button
        context['bookmarked'] = is_bookmarked
        context['format'] = getattr(self, 'format', '')
        if render_items:
            rendered_item = item.render(view, context)
            fragment.add_fragment_resources(rendered_item)
            content = rendered_item.content
        else:
            content = ''
        content_type_gating_service = self.runtime.service(self, 'content_type_gating')
        contains_content_type_gated_content = False
        if content_type_gating_service:
            contains_content_type_gated_content = content_type_gating_service.check_children_for_content_type_gating_paywall(item, self.course_id) is not None
        iteminfo = {'content': content, 'page_title': getattr(item, 'tooltip_title', ''), 'type': item_type, 'id': str(usage_id), 'bookmarked': is_bookmarked, 'path': ' > '.join(display_names + [item.display_name_with_default]), 'graded': item.graded, 'contains_content_type_gated_content': contains_content_type_gated_content}
        if not render_items:
            iteminfo['href'] = context.get('item_url', '').format(usage_key=usage_id)
        if is_user_authenticated:
            if item.location.block_type == 'vertical' and completion_service:
                iteminfo['complete'] = completion_service.vertical_is_complete(item)
        contents.append(iteminfo)
    return contents

def _determine_item_type(self, item):
    return item.get_icon_class() or 'unknown'

def compare_ode_sol(sol1, sol2, func, *args):
    from sympy.core.basic import C, S
    if sol1 == sol2:
        return 0
    if isinstance(sol1, list) or isinstance(sol1, tuple):
        sol1len = sum([len(str(i)) for i in sol1])
        sol1 = sorted(sol1, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol1) - 1]
    else:
        sol1len = len(str(sol1))
    if isinstance(sol2, list) or isinstance(sol2, tuple):
        sol2len = sum([len(str(i)) for i in sol2])
        sol2 = sorted(sol2, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol2) - 1]
    else:
        sol2len = len(str(sol2))
    intcmp = int(sol1.has(C.Integral)) - int(sol2.has(C.Integral))
    if intcmp:
        return intcmp
    sol1s = 0
    sol2s = 0
    if sol1.lhs == func and (not sol1.rhs.has(func)) or (sol1.rhs == func and (not sol1.lhs.has(func))):
        sol1s = 1
    if sol2.lhs == func and (not sol2.rhs.has(func)) or (sol2.rhs == func and (not sol2.lhs.has(func))):
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    try:
        sol1sol = solve(sol1, func)
        if sol1sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol1s = 1
    try:
        sol2sol = solve(sol2, func)
        if sol2sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    return cmp(sol1len, sol2len)

import socket
import re

def reload_graphs(*updates):
    hostname_pattern = re.compile('^[a-zA-Z0-9.-]+$')
    for (hostname, _) in updates:
        if not hostname_pattern.match(hostname):
            raise ValueError(f'Invalid hostname: {hostname}')
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect(settings.SERVERMONITOR_SERVER)
        s.sendall('HOSTNAME==serveradmin.admin\n')
        for (hostname, graphs) in updates:
            for graph in graphs:
                (graph_name, period) = split_graph_name(graph)
                if not period:
                    period = ''
                s.sendall('RELOAD=={graph}##{period}##{hostname}##\n'.format(graph=graph_name, period=period, hostname=hostname))
        s.sendall('DONE\n')
        fileobj = s.makefile()
        return ['SUCCESS' == line.strip() for line in fileobj.readlines()]
    except socket.error:
        return [False] * sum((len(graphs) for (_host, graphs) in updates))

import re

def reload_graphs(*updates):
    hostname_pattern = '^(?!-)[A-Za-z0-9-]{1,63}(?<!-)$'
    for (hostname, _) in updates:
        if not re.match(hostname_pattern, hostname):
            raise ValueError(f'Invalid hostname: {hostname}')
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect(settings.SERVERMONITOR_SERVER)
        s.sendall('HOSTNAME==serveradmin.admin\n')
        for (hostname, graphs) in updates:
