                s.sendall('RELOAD=={graph}##{period}##{hostname}##\n'.format(graph=graph_name, period=period, hostname=hostname))
        s.sendall('DONE\n')
        fileobj = s.makefile()
        return ['SUCCESS' == line.strip() for line in fileobj.readlines()]
    except socket.error:
        return [False] * sum((len(graphs) for (_host, graphs) in updates))

def __init__(self, cursor, scenario_id):
    self.SCENARIO_ID = scenario_id
    optional_feature_columns = ['of_transmission', 'of_transmission_hurdle_rates', 'of_simultaneous_flow_limits', 'of_lf_reserves_up', 'of_lf_reserves_down', 'of_regulation_up', 'of_regulation_down', 'of_frequency_response', 'of_spinning_reserves', 'of_rps', 'of_carbon_cap', 'of_track_carbon_imports', 'of_prm', 'of_elcc_surface', 'of_local_capacity', 'of_markets', 'of_tuning']
    for column in optional_feature_columns:
        setattr(self, column.upper(), cursor.execute(f'SELECT {column} FROM scenarios WHERE scenario_id = {{}};'.format(scenario_id)).fetchone()[0])

def read_files(self):
    bdeps = dict()
    bprov = dict()
    for fname in self.files:
        bin = [x for x in fname.split('@') if x.startswith('binary-')][0][7:]
        if bin not in bdeps:
            bdeps[bin] = dict()
            bprov[bin] = dict()
        try:
            reader = gzip.GzipFile(fname)
        except:
            print('Failed to read file %s' % fname)
            raise Exception()
            continue
        for line in reader.readlines():
            words = line.strip().split(':', 1)
            if words[0] == 'Package':
                pkgname = words[1].strip().rstrip()
                self.pkgnames.add(pkgname)
            elif words[0] == 'Depends':
                bdeps[bin][pkgname] = []
                for dep in words[1].split(','):
                    raw_dep = re.sub('\\(.*\\)', '', dep).strip()
                    if '|' in raw_dep:
                        raw_dep = raw_dep.split('|')[0].strip()
                    bdeps[bin][pkgname].append(raw_dep)
            elif words[0] == 'Provides':
                for pkg in words[1].split(','):
                    dname = pkg.rstrip().strip()
                    if dname not in bprov[bin]:
                        bprov[bin][dname] = set()
                    bprov[bin][dname].add(pkgname)
    self.deps['global'] = dict()
    self.provides['global'] = dict()
    for bin in bdeps:
        self.deps[bin] = dict()
        self.provides[bin] = dict()
    for pkgname in self.pkgnames:
        pset = set()
        for bin in bdeps:
            if pkgname not in bdeps[bin]:
                bdeps[bin][pkgname] = []
            pset.add(tuple(bdeps[bin][pkgname]))
        if len(pset) == 1:
            self.deps['global'][pkgname] = pset.pop()
        else:
            for bin in bdeps:
                self.deps[bin][pkgname] = bdeps[bin][pkgname]
    provided = set()
    for bin in bprov:
        for prov in bprov[bin]:
            provided.add(prov)
    for prov in provided:
        prset = set()
        for bin in bprov:
            if prov not in bprov[bin]:
                continue
            prset.add(tuple(bprov[bin].get(prov, ())))
        if len(prset) == 1:
            self.provides['global'][prov] = prset.pop()
        else:
            for bin in bprov:
                self.provides[bin][prov] = bprov[bin].get(prov, ())
    self.save_state()

