def ProcessTimelineEvent(self, timeline_event, parent):
    import bisect
    start = timeline_event['s'] - self.start_time
    end = timeline_event['e'] - self.start_time
    if end > start:
        elapsed = end - start
        thread = timeline_event['t']
        name = self.event_name_lookup[timeline_event['n']]
        if 'main_thread' in self.cpu and thread == self.cpu['main_thread']:
            if elapsed > 50000:
                if start - self.interactive_start > 500000:
                    self.interactive.append([int(math.ceil(self.interactive_start / 1000.0)), int(math.floor(start / 1000.0))])
                self.interactive_start = end
                self.interactive_end = None
            else:
                self.interactive_end = end
        if 'js' in timeline_event:
            script = timeline_event['js']
            js_start = start / 1000.0
            js_end = end / 1000.0
            if self.scripts is None:
                self.scripts = {}
            if 'main_thread' not in self.scripts and 'main_thread' in self.cpu:
                self.scripts['main_thread'] = self.cpu['main_thread']
            if thread not in self.scripts:
                self.scripts[thread] = {}
            if script not in self.scripts[thread]:
                self.scripts[thread][script] = {}
            if name not in self.scripts[thread][script]:
                self.scripts[thread][script][name] = []
            periods = self.scripts[thread][script][name]
            new_duration = True
            i = bisect.bisect_left(periods, [js_start, js_end])
            if i > 0:
                prev = periods[i - 1]
                if len(prev) >= 2 and js_start >= prev[0] and (js_end <= prev[1]):
                    new_duration = False
            if new_duration and i < len(periods):
                nxt = periods[i]
                if len(nxt) >= 2 and js_start >= nxt[0] and (js_end <= nxt[1]):
                    new_duration = False
            if new_duration:
                periods.insert(i, [js_start, js_end])
        slice_usecs = self.cpu['slice_usecs']
        first_slice = int(float(start) / float(slice_usecs))
        last_slice = int(float(end) / float(slice_usecs))
        for slice_number in xrange(first_slice, last_slice + 1):
            slice_start = slice_number * slice_usecs
            slice_end = slice_start + slice_usecs
            used_start = max(slice_start, start)
            used_end = min(slice_end, end)
            slice_elapsed = used_end - used_start
            self.AdjustTimelineSlice(thread, slice_number, name, parent, slice_elapsed)
        if 'c' in timeline_event:
            for child in timeline_event['c']:
                self.ProcessTimelineEvent(child, name)

def _walk_vdi_chain(session, vdi_uuid):
    while True:
        vdi_ref = session.call_xenapi('VDI.get_by_uuid', vdi_uuid)
        vdi_rec = session.call_xenapi('VDI.get_record', vdi_ref)
        yield vdi_rec
        parent_uuid = vdi_rec['sm_config'].get('vhd-parent')
        if parent_uuid:
            vdi_uuid = parent_uuid
        else:
            break

def _get_vhd_parent(session, vdi_uuid):
    for vdi_rec in _walk_vdi_chain(session, vdi_uuid):
        return vdi_rec

def _log(self, level, msg, args, exc_info=None, extra=None, context=None):
    if not extra:
        extra = {}
    if context:
        extra.update(_dictify_context(context))
    extra.update({'nova_version': version.string_with_vcs()})
    logging.Logger._log(self, level, msg, args, exc_info, extra)

def get_type(self, names):
    assert isinstance(names, list)
    typ = None
    for type_specifier in names:
        if type_specifier == 'int':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'void':
            typ = nodes.VoidType()
        elif type_specifier == 'char':
            typ = nodes.IntegerType('char')
        elif type_specifier == 'float':
            typ = nodes.FloatingPointType('float')
        elif type_specifier == 'double':
            typ = nodes.FloatingPointType('double')
        elif type_specifier == 'unsigned':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'signed':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'short':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'long':
            typ = nodes.IntegerType('int')
        else:
            raise NotImplementedError(str(type_specifier))
    return typ

