def import_jurisdiction(org_importer, jurisdiction):
    metadata = jurisdiction.get_metadata()
    metadata['_type'] = 'metadata'
    metadata['_id'] = jurisdiction.jurisdiction_id
    metadata['latest_update'] = datetime.datetime.utcnow()
    if 'name' not in metadata or not metadata['name']:
        raise ValueError('Metadata must contain a valid name.')
    if 'parties' not in metadata or not isinstance(metadata['parties'], list):
        raise ValueError('Metadata must contain a valid list of parties.')
    db.metadata.save(metadata)
    org = {'_type': 'organization', 'classification': 'jurisdiction', 'parent_id': None, 'jurisdiction_id': jurisdiction.jurisdiction_id, 'name': metadata['name']}
    if 'other_names' in metadata:
        org['other_names'] = metadata['other_names']
    if 'parent_id' in metadata:
        org['parent_id'] = metadata['parent_id']
    org_importer.import_object(org)
    for party in metadata['parties']:
        org = {'_type': 'organization', 'classification': 'party', 'name': party['name'], 'parent_id': None}
        org_importer.import_object(org)

def _render_to_grayscale(self) -> np.ndarray:
    self.viewer.observer_vehicle = self.observer_vehicle
    self.viewer.display()
    raw_rgb = self.viewer.get_image()
    raw_rgb = np.moveaxis(raw_rgb, 0, 1)
    return np.dot(raw_rgb[..., :3], self.weights).clip(0, 255).astype(np.uint8)

def _render_to_grayscale(self) -> np.ndarray:
