def add_provisioning_network(self, task):
    LOG.debug('Binding flat network ports')
    node = task.node
    host_id = node.instance_info.get('nova_host_id')
    if not host_id:
        return
    ports = [p for p in task.ports if not p.portgroup_id]
    portgroups = task.portgroups
    client = neutron.get_client(task.context.auth_token)
    for port_like_obj in ports + portgroups:
        vif_port_id = port_like_obj.extra.get('vif_port_id') or port_like_obj.internal_info.get('tenant_vif_port_id')
        if not vif_port_id:
            continue
        body = {'port': {'binding:host_id': host_id}}
        try:
            client.update_port(vif_port_id, body)
        except neutron_exceptions.NeutronClientException as e:
            msg = _('Unable to set binding:host_id for neutron port %(port_id)s. Error: %(err)s') % {'port_id': vif_port_id, 'err': e}
            LOG.exception(msg)
            raise exception.NetworkError(msg)

def report_gradient(self, grads, variables):
