def on_entry_duplicate_menu_button_clicked(self, _action, _param):
    self.start_database_lock_timer()
    self.database_manager.duplicate_entry(self.current_element.entry)
    parent_group = self.current_element.parentgroup
    if self.database_manager.check_is_root_group(parent_group) is True:
        self.pathbar.on_home_button_clicked(self.pathbar.home_button)
    else:
        for button in self.pathbar.buttons:
            if button.element.uuid == parent_group.uuid:
                self.pathbar.on_pathbar_button_clicked(button)
    self.current_element = parent_group
    self.show_page_of_new_directory(False, False)

def _gap_init_(self):
    if not self.is_finite():
        return 'AbelianPcpGroup(%s)' % list(self.invariants())
    return 'AbelianGroup(%s)' % list(self.gens_orders())

def _gap_init_(self):
    from sage.groups.abelian_gps.polycyclic import AbelianPcpGroup
    if not self.is_finite():
        return 'AbelianPcpGroup(%s)' % list(self.invariants())
    return 'AbelianGroup(%s)' % list(self.gens_orders())

def _hadoop_streaming_commands(self, step_num):
    version = self.get_hadoop_version()
    (mapper, bash_wrap_mapper) = self._render_substep(step_num, 'mapper')
    (combiner, bash_wrap_combiner) = self._render_substep(step_num, 'combiner')
    (reducer, bash_wrap_reducer) = self._render_substep(step_num, 'reducer')
    if combiner is not None and (not supports_combiners_in_hadoop_streaming(version)):
        mapper = '%s | sort | %s' % (mapper, combiner)
        combiner = None
        bash_wrap_combiner = False
    if bash_wrap_mapper:
        mapper = bash_wrap(mapper)
    if bash_wrap_combiner:
        combiner = bash_wrap(combiner)
    if bash_wrap_reducer:
        reducer = bash_wrap(reducer)
    return (mapper, combiner, reducer)

def ParseID3v1(string):
    from struct import error as StructError
    frames = {}
    try:
        (tag, title, artist, album, year, comment, track, genre) = unpack('3s30s30s30s4s29sbb', string)
    except StructError:
        return None
    if tag != 'TAG':
        return None
    title = title.strip('\x00').strip().decode('latin1')
    artist = artist.strip('\x00').strip().decode('latin1')
    album = album.strip('\x00').strip().decode('latin1')
    year = year.strip('\x00').strip().decode('latin1')
    comment = comment.strip('\x00').strip().decode('latin1')
    if title:
        frames['TIT2'] = TIT2(encoding=0, text=title)
    if artist:
        frames['TPE1'] = TPE1(encoding=0, text=[artist])
    if album:
        frames['TALB'] = TALB(encoding=0, text=album)
    if year:
        frames['TYER'] = TYER(encoding=0, text=year)
    if comment:
        frames['COMM'] = COMM(encoding=0, lang='eng', desc='ID3v1 Comment', text=comment)
    if track:
        frames['TRCK'] = TRCK(encoding=0, text=str(track))
    frames['TCON'] = TCON(encoding=0, text=str(genre))
    if version_requested == 2.4:
        frames['TDRC'] = TDRC(encoding=0, text=current_date)
    return frames

def ParseID3v1(string, version_requested=None):
    from struct import error as StructError
    frames = {}
    try:
        (tag, title, artist, album, year, comment, track, genre) = unpack('3s30s30s30s4s29sbb', string)
    except StructError:
        return None
    if tag != 'TAG':
        return None
    title = title.strip('\x00').strip().decode('latin1')
    artist = artist.strip('\x00').strip().decode('latin1')
    album = album.strip('\x00').strip().decode('latin1')
    year = year.strip('\x00').strip().decode('latin1')
    comment = comment.strip('\x00').strip().decode('latin1')
    if title:
        frames['TIT2'] = TIT2(encoding=0, text=title)
    if artist:
        frames['TPE1'] = TPE1(encoding=0, text=[artist])
    if album:
        frames['TALB'] = TALB(encoding=0, text=album)
    if version_requested == '2.4':
        frames['TDRC'] = TDRC(encoding=0, text=current_date())
    if year:
        frames['TYER'] = TYER(encoding=0, text=year)
    if comment:
        frames['COMM'] = COMM(encoding=0, lang='eng', desc='ID3v1 Comment', text=comment)
    if track:
        frames['TRCK'] = TRCK(encoding=0, text=str(track))
    frames['TCON'] = TCON(encoding=0, text=str(genre))
    return frames

import locale

def __get_ocrlang(self):
    try:
        ocrlang = self._configparser.get('OCR', 'Lang')
        if ocrlang == 'None':
            return None
        return ocrlang
    except ConfigParser.NoOptionError:
        return locale.getdefaultlocale()[0]

def aspirate(self, pipette_id: str, labware_id: str, well_name: str, well_location: WellLocation, volume: float, flowRate: float) -> commands.AspirateResult:
    request = commands.AspirateCreate(params=commands.AspirateParams(pipetteId=pipette_id, labwareId=labware_id, wellName=well_name, wellLocation=well_location, volume=volume, flowRate=flowRate))
    result = self._transport.execute_command(request=request)
    return cast(commands.AspirateResult, result)

def add_mapping_data(dp_id, clks):
    if not isinstance(clks, list) or not clks:
        raise ValueError("'clks' must be a non-empty list")
    if not all((isinstance(clk, str) for clk in clks)):
        raise ValueError("All elements in 'clks' must be strings")
    receipt_token = generate_code()
    db.insert_raw_filter_data(get_db(), clks, dp_id, receipt_token)
    return receipt_token

def sample_boundaries(blocks: List[ObjectRef[Block]], sort_key: SortKey, num_reducers: int) -> List[T]:
    columns = sort_key.get_columns()
    n_samples = int(num_reducers * 10 / len(blocks))
    sample_block = cached_remote_fn(_sample_block)
    sample_results = [sample_block.remote(block, n_samples, sort_key) for block in blocks]
    if sample_bar is None:
        sample_bar = ProgressBar(SortTaskSpec.SORT_SAMPLE_SUB_PROGRESS_BAR_NAME, len(blocks) * n_samples, unit='rows')
    samples = sample_bar.fetch_until_complete(sample_results)
    del sample_results
    samples: List[Block] = [s for s in samples if len(s) > 0]
    if len(samples) == 0:
        return [None] * (num_reducers - 1)
    builder = DelegatingBlockBuilder()
    for sample in samples:
        builder.add_block(sample)
    samples_table = builder.build()
    samples_dict = BlockAccessor.for_block(samples_table).to_numpy(columns=columns)
    samples_list = list(zip(*samples_dict.values()))

    def is_na(x):
        if x is None:
            return True
        x = np.asarray(x)
        if np.issubdtype(x.dtype, np.number):
            return np.isnan(x)
        return False
    for (i, desc) in list(enumerate(sort_key.get_descending()))[::-1]:
        samples_list.sort(key=lambda sample: NULL_SENTINEL if is_na(sample[i]) else sample[i], reverse=desc)
    quantile_indices = [int(q * (len(samples_list) - 1)) for q in np.linspace(0, 1, num_reducers + 1)]
    return [samples_list[i] for i in quantile_indices[1:-1]]

def sample_boundaries(blocks: List[ObjectRef[Block]], sort_key: SortKey, num_reducers: int) -> List[T]:
    columns = sort_key.get_columns()
    if len(columns) < 1:
        raise ValueError('At least one boundary sampling key must be provided.')
    n_samples = int(num_reducers * 10 / len(blocks))
    sample_block = cached_remote_fn(_sample_block)
    sample_results = [sample_block.remote(block, n_samples, sort_key) for block in blocks]
    if sample_bar is None:
        sample_bar = ProgressBar(SortTaskSpec.SORT_SAMPLE_SUB_PROGRESS_BAR_NAME, len(blocks) * n_samples, unit='rows')
    samples = sample_bar.fetch_until_complete(sample_results)
    del sample_results
    samples: List[Block] = [s for s in samples if len(s) > 0]
    if len(samples) == 0:
        return [None] * (num_reducers - 1)
    builder = DelegatingBlockBuilder()
    for sample in samples:
        builder.add_block(sample)
    samples_table = builder.build()
    samples_dict = BlockAccessor.for_block(samples_table).to_numpy(columns=columns)
    samples_list = list(zip(*samples_dict.values()))

    def is_na(x):
        if x is None:
            return True
        x = np.asarray(x)
        if np.issubdtype(x.dtype, np.number):
            return np.isnan(x)
        return False
    for (i, desc) in list(enumerate(sort_key.get_descending()))[::-1]:
        samples_list.sort(key=lambda sample: NULL_SENTINEL if is_na(sample[i]) else sample[i], reverse=desc)
    quantile_indices = [int(q * (len(samples_list) - 1)) for q in np.linspace(0, 1, num_reducers + 1)]
    return [samples_list[i] for i in quantile_indices[1:-1]]

