def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from scipy.sparse._bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        from scipy.sparse._bsr import bsr_matrix
        (R, C) = self.shape
        (r_block, c_block) = blocksize
        if R % r_block != 0 or C % c_block != 0:
            raise ValueError('blocksize must divide matrix dimensions exactly')
        n_block_rows = R // r_block
        n_block_cols = C // c_block
        indptr = [0]
        indices = []
        data_blocks = []
        for i in range(n_block_rows):
            row_start = self.indptr[i * r_block]
            row_end = self.indptr[(i + 1) * r_block]
            block_dict = {}
            for row in range(i * r_block, (i + 1) * r_block):
                start = self.indptr[row]
                end = self.indptr[row + 1]
                for idx in range(start, end):
                    col = self.indices[idx]
                    block_col = col // c_block
                    if block_col not in block_dict:
                        block_dict[block_col] = self.data[idx] * 0
                    block_dict[block_col] += self.data[idx] * 0
            for row in range(i * r_block, (i + 1) * r_block):
                start = self.indptr[row]
                end = self.indptr[row + 1]
                for idx in range(start, end):
                    col = self.indices[idx]
                    block_col = col // c_block
                    if block_col not in block_dict:
                        block_dict[block_col] = self.data[idx] * 0
                    if block_col in block_dict:
                        if block_dict[block_col].shape == ():
                            block_dict[block_col] = self.data[idx] * 0
                        if block_dict[block_col].shape == ():
                            block_dict[block_col] = self.data[idx] * 0
            for block_col in sorted(block_dict.keys()):
                block = self.data[i * r_block:(i + 1) * r_block, block_col * c_block:(block_col + 1) * c_block]
                data_blocks.append(block)
                indices.append(block_col)
            indptr.append(len(indices))
        data = np.array(data_blocks)
        indptr = np.array(indptr)
        indices = np.array(indices)
        return bsr_matrix((data, indices, indptr), shape=self.shape, copy=copy)

def new_path(road_map: MapInterface, trace: Trace, distance_epsilon: float, weight_type: str='minutes') -> List[Road]:
    if len(trace.coords) < 1:
        return []
    origin = trace.coords[0]
    destination = trace.coords[-1]
    time_path = road_map.shortest_path(origin, destination, weight=weight_type)
    dist_path = road_map.shortest_path(origin, destination, weight='meters')
    time_score = score(trace, time_path, distance_epsilon)
    dist_score = score(trace, dist_path, distance_epsilon)
    if dist_score > time_score:
        return dist_path
    else:
        return time_path

def get_latest_source_version(self) -> str:
    try:
        yeastmine_release_response = requests.get('https://yeastmine.yeastgenome.org/yeastmine/service/version/release', timeout=10)
        yeastmine_release_response.raise_for_status()
        release_text = yeastmine_release_response.text
        if 'Data Updated on:' in release_text and '; GO-Release' in release_text:
            release_version = release_text.split('Data Updated on:')[1].split('; GO-Release')[0].strip()
            return release_version
        else:
            self.logger.warning('Unexpected format in yeastmine release response; returning fallback version.')
            return 'yeast_v1'
    except Exception as e:
        self.logger.warning(f'Failed to get latest source version from yeastmine: {e}; returning fallback version.')
        return 'yeast_v1'

def pretty_list(rtlst, header, sortBy=0):
    _l_header = len(header[0])
    _space = '  '
    rtlst.sort(key=lambda x: x[sortBy])
    rtlst = header + rtlst
    colwidth = [max((len(str(y)) for y in x)) for x in zip(*rtlst)]
    width = get_terminal_width()
    if width:
        if sum(colwidth) > width:
            _med = width // _l_header - (1 if WINDOWS else 0)
            while sum(colwidth) + 6 > width:
                _max = max(colwidth)
                colwidth = [_med if x == _max else x for x in colwidth]

            def _crop(x, width):
                return x[:width - 3] + '...' if len(x) > width else x
            rtlst = [tuple((_crop(str(rtlst[j][i]), colwidth[i]) for i in range(len(rtlst[j])))) for j in range(len(rtlst))]
            colwidth = [max((len(str(y)) for y in x)) for x in zip(*rtlst)]
    fmt = _space.join(['%%-%ds' % x for x in colwidth])
    return '\n'.join((fmt % x for x in rtlst))

import struct
from datetime import datetime, timedelta
import dateutil.parser
import socket
import codecs
cb_datetime_format = '%Y-%m-%d %H:%M:%S.%f'
solr_datetime_format = '%Y-%m-%dT%H:%M:%S.%fZ'
sign_datetime_format = '%Y-%m-%dT%H:%M:%SZ'
'Create a Cb 4.2-style GUID from components'

def create_42_guid(sensor_id, proc_pid, proc_createtime):
    full_guid = codecs.encode(struct.pack('>IIQ', sensor_id, proc_pid, proc_createtime), 'hex')
    return '%s-%s-%s-%s-%s' % (full_guid[:8], full_guid[8:12], full_guid[12:16], full_guid[16:20], full_guid[20:])

def parse_42_guid(guid):
    guid_parts = guid.split('-')
    guid_int = codecs.decode(''.join(guid_parts)[:32], 'hex')
    return struct.unpack('>IIQ', guid_int)

def parse_process_guid(guid):
    (sensor_id, proc_pid, proc_createtime) = parse_42_guid(guid)
    return (sensor_id, proc_pid, datetime(1601, 1, 1) + timedelta(microseconds=proc_createtime / 10))

def convert_to_solr(dt):
    return dt.strftime(solr_datetime_format)

def convert_from_solr(s):
    if s == -1:
        return datetime.fromtimestamp(0)
    try:
        return datetime.strptime(s, solr_datetime_format)
    except ValueError:
        return datetime.strptime(s, sign_datetime_format)

def convert_from_cb(s):
    if s is None:
        return dateutil.parser.parse('1970-01-01T00:00:00Z')
    else:
        return dateutil.parser.parse(s)

def convert_event_time(s):
    return convert_from_cb(s).replace(tzinfo=None)

def convert_to_cb(dt):
    return dt.strftime(cb_datetime_format)

def get_constants(prefix):
    return dict(((getattr(socket, n), n) for n in dir(socket) if n.startswith(prefix)))
protocols = get_constants('IPPROTO_')

def __init__(self, version: int=MAX_TEAL_VERSION):
    self.teal_version = version
    self.attrs = {m: (getattr(self, m), getattr_static(self, m)) for m in list(set(dir(self.__class__)) - set(dir(super()))) if not m.startswith('__')}
    self.hints: dict[str, MethodHints] = {}
    self.bare_handlers: dict[str, OnCompleteAction] = {}
    self.methods: dict[str, tuple[ABIReturnSubroutine, MethodConfig]] = {}
    acct_vals: dict[str, AccountStateValue | DynamicAccountStateValue] = {}
    app_vals: dict[str, ApplicationStateValue | DynamicApplicationStateValue] = {}
    for (name, (bound_attr, static_attr)) in self.attrs.items():
        match bound_attr:
            case AccountStateValue():
                if bound_attr.key is None:
                    bound_attr.key = Bytes(name)
                acct_vals[name] = bound_attr
            case DynamicAccountStateValue():
                acct_vals[name] = bound_attr
            case ApplicationStateValue():
                if bound_attr.key is None:
                    bound_attr.key = Bytes(name)
                app_vals[name] = bound_attr
            case DynamicApplicationStateValue():
                app_vals[name] = bound_attr
        if name in app_vals or name in acct_vals:
            continue
        handler_config = get_handler_config(bound_attr)
        match handler_config:
            case HandlerConfig(bare_method=BareCallActions()):
                actions = {oc: cast(OnCompleteAction, action) for (oc, action) in handler_config.bare_method.__dict__.items() if action is not None}
                for (oc, action) in actions.items():
                    if oc in self.bare_handlers:
                        raise BareOverwriteError(oc)
                    if handler_config.referenced_self:
                        action.action.subroutine.implementation = bound_attr
                    self.bare_handlers[oc] = action
            case HandlerConfig(method_spec=Method()):
                abi_meth = ABIReturnSubroutine(static_attr)
                if handler_config.referenced_self:
                    abi_meth.subroutine.implementation = bound_attr
                self.methods[name] = abi_meth
                self.hints[name] = handler_config.hints()
            case HandlerConfig(subroutine=Subroutine()):
                if handler_config.referenced_self:
                    setattr(self, name, handler_config.subroutine(bound_attr))
                else:
                    setattr(self.__class__, name, handler_config.subroutine(static_attr))
    self.acct_state = AccountState(acct_vals)
    self.app_state = ApplicationState(app_vals)
    self.router = Router(name=self.__class__.__name__, bare_calls=BareCallActions(**self.bare_handlers), description=self.__doc__)
    for method in self.methods.values():
        self.router.add_method_handler(method_call=method, method_config=handler_config.method_config)
    (self.approval_program, self.clear_program, self.contract) = self.router.compile_program(version=self.teal_version, assemble_constants=True, optimize=OptimizeOptions(scratch_slots=True))

def update_table_column_types(schema, table_name, engine, metadata):
    table = reflect_table(table_name, schema, engine, metadata=metadata)
    inferable_column_names = (col.name for col in table.columns if not MathesarColumn.from_column(col).is_default and (not col.primary_key) and (not col.foreign_keys))
    for column_name in inferable_column_names:
        infer_column_type(schema, table_name, column_name, engine)

