def export_svg(self) -> None:
    (path, _) = QtWidgets.QFileDialog.getSaveFileName(self, caption='Save SVG File', filter='SVG Files (*.svg)')
    if not path:
        return
    try:
        t0 = time.perf_counter()
        with open(path, 'wt') as fp:
            fp.write(self.make_svg_string())
        self.show_message(f'SVG successfully in {time.perf_counter() - t0:.2f}s exported')
    except IOError as e:
        QtWidgets.QMessageBox.critical(self, 'Export Error', str(e))

def test_json_encode_decode(self):
    op_meta_info = OpMetaInfo('x.y.Z')
    op_meta_info.header['description'] = 'Hello!'
    op_meta_info.input['x'] = {'data_type': str}
    op_meta_info.input['y'] = {'data_type': int}
    op_meta_info.output[RETURN] = {'data_type': str}
    d1 = op_meta_info.to_json()
    d2 = json.loads(d1)
    self.assertEqual(d2, json.loads(d1))

class OpMetaInfo:

    def __init__(self, qualified_name):
        self.qualified_name = qualified_name
        self.header = {}
        self.input = {}
        self.output = {}

    def to_json(self):

        def io_def_namespace_to_dict(io_def_namespace):
            io_def_dict = OrderedDict(io_def_namespace)
            for (name, properties) in io_def_dict.items():
                properties_copy = dict(properties)
                if 'data_type' in properties_copy:
                    properties_copy['data_type'] = object_to_qualified_name(properties_copy['data_type'])
                io_def_dict[name] = properties_copy
            return io_def_dict
        d1 = OrderedDict()
        d1['qualified_name'] = self.qualified_name
        d1['header'] = self.header
        d1['input'] = io_def_namespace_to_dict(self.input)
        d1['output'] = io_def_namespace_to_dict(self.output)
        return json.dumps(d1, indent='  ')

def copy_worker(event, lambda_context):

    class CopyWorkerTimedThread(TimedThread[dict]):

        def __init__(self, timeout_seconds: float, state: dict) -> None:
            super().__init__(timeout_seconds, state)
            self.gcp_client = Config.get_native_handle(Replica.gcp)
            self.source_bucket = state[Key.SOURCE_BUCKET]
            self.source_key = state[Key.SOURCE_KEY]
            self.source_crc32c = state[_Key.SOURCE_CRC32C]
            self.destination_bucket = state[Key.DESTINATION_BUCKET]
            self.destination_key = state[Key.DESTINATION_KEY]
            self.size = state[_Key.SIZE]

        def run(self) -> dict:
            state = self.get_state_copy()
            src_blob = self.gcp_client.bucket(self.source_bucket).get_blob(self.source_key)
            dst_blob = self.gcp_client.bucket(self.destination_bucket).blob(self.destination_key)
            content_type = src_blob.content_type or 'application/octet-stream'
            will_cache = should_cache_file(content_type, self.size)
            if not will_cache:
                logger.info('Not caching %s with content-type %s size %s', self.source_key, content_type, self.size)
            if not will_cache and is_dss_bucket(self.destination_bucket):
                dst_blob._patch_property('storageClass', 'STANDARD')
                dst_blob._patch_property('contentType', content_type)
            while True:
                response = dst_blob.rewrite(src_blob, token=state.get(_Key.TOKEN, None))
                if response[0] is None:
                    state[Key.FINISHED] = True
                    return state
                else:
                    state[_Key.TOKEN] = response[0]
                    self.save_state(state)
    return CopyWorkerTimedThread(lambda_context.get_remaining_time_in_millis() / 1000 - 10, event).start()

def reshape(ctx: LoweringRuleContext, op, aval_out: core.AbstractValue) -> ir.Value:
    if dtypes.is_opaque_dtype(aval_out.dtype):
        aval_out_physical_avals = aval_out.dtype._rules.physical_avals(aval_out)
        assert len(aval_out_physical_avals) == 1, 'Expected a single physical aval.'
        (aval_out,) = aval_out_physical_avals
        assert aval_out.shape == aval_out_physical_avals[0].shape, 'Reshape must match the output physical aval shape.'
    if not core.is_constant_shape(aval_out.shape):
        shape = eval_dynamic_shape(ctx, aval_out.shape)
        return hlo.DynamicReshapeOp(aval_to_ir_type(aval_out), op, shape_tensor(shape)).result
    else:
        return hlo.ReshapeOp(aval_to_ir_type(aval_out), op).result

def test_getString(self):
    v = cssutils.css.CSSPrimitiveValue(u'1px')
    self.assert_(v.primitiveType == v.CSS_PX)
    self.assertRaises(xml.dom.InvalidAccessErr, v.getStringValue)
    pv = cssutils.css.CSSPrimitiveValue
    tests = {pv.CSS_STRING: ("'red'", 'red'), pv.CSS_STRING: ('"red"', 'red'), pv.CSS_URI: ('url(http://example.com)', None), pv.CSS_URI: ("url('http://example.com')", u'http://example.com'), pv.CSS_URI: ('url("http://example.com")', u'http://example.com'), pv.CSS_URI: ('url("http://example.com?)")', u'http://example.com?)'), pv.CSS_IDENT: ('red', None), pv.CSS_ATTR: ('attr(att-name)', u'att-name')}
    for t in tests:
        (val, exp) = tests[t]
        if not exp:
            exp = val
        v = cssutils.css.CSSPrimitiveValue(val)
        self.assertEqual(v.primitiveType, t)
        self.assertEqual(v.getStringValue(), exp)

def create(self):
    dir_path = self.dir_path
    if not exists(dir_path):
        try:
            os.makedirs(dir_path, 493)
        except OSError as e:
            if not exists(dir_path):
                logger.warning('Cannot create directory %s (%s)', dir_path, e)
                raise self.Error('The directory {} cannot be created.'.format(dir_path)) from e
    name = secure_filename(self.name)
    (name_root, name_ext) = splitext(name)
    current_name_root = name_root
    max_trials = self.max_trials
    max_length = self.max_length - len(name_ext)
    trials = 0
    for generator_cls in self._generators_classes:
        for suffix in generator_cls():
            trials += 1
            root_max_len = max_length - len(suffix)
            if root_max_len < 0:
                raise self.Error('No unique filename has been found with the current rules (max length too short for suffix alone).')
            current_name_root = name_root[:root_max_len] + suffix
            final_path = join(dir_path, current_name_root + name_ext)
            try:
                f = open(final_path, 'x')
            except FileExistsError as e:
                if trials >= max_trials:
                    raise self.Error('No unique filename has been found with the current rules (max trials reached).') from e
            else:
                f.close()
                return final_path
        else:
            name_root = current_name_root
    raise self.Error('No unique filename has been found with the current rules.')

def _build_key(self, key, namespace=None):
    if namespace is not None:
        return '{}{}'.format(namespace, key)
    if self.namespace is not None:
        return '{}{}'.format(self.namespace, key)
    return key

def _modular_symbol_0_to_alpha(self, alpha, i=0):
    if alpha.is_infinity():
        return self.manin_symbol((i, 0, 1), check=False)
    (v, c) = arith.continued_fraction_list(alpha._rational_(), partial_convergents=True)
    a = self(0)
    if self.weight() > 2:
        a += self.some_polynomial_action(alpha)
    for k in range(1, len(c)):
        u = c[k][1]
        v = c[k - 1][1]
        if k % 2 == 0:
            v = -v
        x = self.manin_symbol((i, u, v), check=False)
        a += x
    return a

def _modular_symbol_0_to_alpha(self, alpha, i=0):
    if alpha.is_infinity():
        return self.manin_symbol((i, 0, 1), check=False)
    (v, c) = arith.continued_fraction_list(alpha._rational_(), partial_convergents=True)
    a = self(0)
    if self.weight() > 2:
        from sage.rings.polynomial.polynomial_ring import PolynomialRing
        R = PolynomialRing(self.base_ring(), 'X,Y')
        (X, Y) = R.gens()
        poly = (X - alpha * Y) ** (self.weight() - 2)
        a = a * poly
    for k in range(1, len(c)):
        u = c[k][1]
        v = c[k - 1][1]
        if k % 2 == 0:
            v = -v
        x = self.manin_symbol((i, u, v), check=False)
        a += x
    return a

def firewall_reload(skip_upnp=False):
    from yunohost.hook import hook_callback
    reloaded = False
    errors = False
    ssh_port = _get_ssh_port()
    if ssh_port not in firewall_list()['opened_ports']:
        firewall_allow('TCP', ssh_port, no_reload=True)
    firewall = firewall_list(raw=True)
    upnp = firewall_upnp()['enabled'] if not skip_upnp else False
    try:
        process.check_output('iptables -w -L')
    except process.CalledProcessError as e:
        logger.debug('iptables seems to be not available, it outputs:\n%s', prependlines(e.output.rstrip(), '> '))
        logger.warning(m18n.n('iptables_unavailable'))
    else:
        rules = ['iptables -w -F', 'iptables -w -X', 'iptables -w -A INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT']
        for protocol in ['TCP', 'UDP']:
            for port in firewall['ipv4'][protocol]:
                rules.append('iptables -w -A INPUT -p %s --dport %s -j ACCEPT' % (protocol, process.quote(str(port))))
        rules += ['iptables -w -A INPUT -i lo -j ACCEPT', 'iptables -w -A INPUT -p icmp -j ACCEPT', 'iptables -w -P INPUT DROP']
        if process.run_commands(rules, callback=_on_rule_command_error):
            errors = True
        reloaded = True
    try:
        process.check_output('ip6tables -L')
    except process.CalledProcessError as e:
        logger.debug('ip6tables seems to be not available, it outputs:\n%s', prependlines(e.output.rstrip(), '> '))
        logger.warning(m18n.n('ip6tables_unavailable'))
    else:
        rules = ['ip6tables -w -F', 'ip6tables -w -X', 'ip6tables -w -A INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT']
        for protocol in ['TCP', 'UDP']:
            for port in firewall['ipv6'][protocol]:
                rules.append('ip6tables -w -A INPUT -p %s --dport %s -j ACCEPT' % (protocol, process.quote(str(port))))
        rules += ['ip6tables -w -A INPUT -i lo -j ACCEPT', 'ip6tables -w -A INPUT -p icmpv6 -j ACCEPT', 'ip6tables -w -P INPUT DROP']
        if process.run_commands(rules, callback=_on_rule_command_error):
            errors = True
        reloaded = True
    if not reloaded:
        raise YunohostError('firewall_reload_failed')
    hook_callback('post_iptable_rules', args=[upnp, os.path.exists('/proc/net/if_inet6')])
    if upnp:
        firewall_upnp(no_refresh=False)
    service_restart('fail2ban')
    if errors:
        logger.warning(m18n.n('firewall_rules_cmd_failed'))
    else:
        logger.success(m18n.n('firewall_reloaded'))
    return firewall_list()

def call(self, node, unused_func, posargs, namedargs, starargs=None, starstarargs=None, new_locals=None):
    if self.vm.is_at_maximum_depth():
        log.info('Maximum depth reached. Not analyzing %r', self.name)
        return self.vm.program.NewUnsolvable(node)
    self._check_call(node, posargs, namedargs, starargs, starstarargs)
    callargs = self._map_args(node, posargs, namedargs, starargs, starstarargs)
    frame = self.vm.make_frame(node, self.code, callargs, self.f_globals, self.f_locals, self.closure, new_locals=new_locals)
    if self.vm.options.skip_repeat_calls:
        callkey = self._hash_all((callargs, None), (frame.f_globals.members, set(self.code.co_names)), (frame.f_locals.members, set(self.code.co_varnames)))
    else:
        callkey = len(self._call_records)
    if callkey in self._call_records:
        (_, old_ret, _) = self._call_records[callkey]
        ret = self.vm.program.NewVariable(old_ret.name, old_ret.data, [], node)
        return (node, ret)
    if self.code.co_flags & loadmarshal.CodeType.CO_GENERATOR:
        generator = Generator(frame, self.vm)
        (node2, _) = generator.run_until_yield(node)
        (node_after_call, ret) = (node2, generator.to_variable(node2, self.name))
    else:
        (node_after_call, ret) = self.vm.run_frame(frame, node)
    self._call_records[callkey] = (callargs, ret, node_after_call)
    self.last_frame = frame
    return (node_after_call, ret)

def __init__(self, environment, kwargs):
    super().__init__('boost', environment, 'cpp', kwargs)
    self.need_static_link = ['boost_exception', 'boost_test_exec_monitor']
    self.is_debug = environment.cmd_line_options.buildtype in ['debug', 'debugoptimized']
    threading = kwargs.get('threading', 'multi')
    self.is_multithreading = threading == 'multi'
    self.requested_modules = self.get_requested(kwargs)
    self.boost_root = None
    self.boost_roots = []
    self.incdir = None
    self.libdir = None
    if 'BOOST_ROOT' in os.environ:
        self.boost_root = os.environ['BOOST_ROOT']
        self.boost_roots = [self.boost_root]
        if not os.path.isabs(self.boost_root):
            raise DependencyException('BOOST_ROOT must be an absolute path.')
    if 'BOOST_INCLUDEDIR' in os.environ:
        self.incdir = os.environ['BOOST_INCLUDEDIR']
    if 'BOOST_LIBRARYDIR' in os.environ:
        self.libdir = os.environ['BOOST_LIBRARYDIR']
    if self.boost_root is None:
        if mesonlib.for_windows(self.want_cross, self.env):
            self.boost_roots = self.detect_win_roots()
        else:
            self.boost_roots = self.detect_nix_roots()
    if self.incdir is None:
        if mesonlib.for_windows(self.want_cross, self.env):
            self.incdir = self.detect_win_incdir()
        else:
            self.incdir = self.detect_nix_incdir()
    if self.check_invalid_modules():
        self.log_fail()
        return
    mlog.debug('Boost library root dir is', mlog.bold(self.boost_root))
    mlog.debug('Boost include directory is', mlog.bold(self.incdir))
    self.detect_headers_and_version()
    if self.is_found:
        self.detect_lib_modules()
        mlog.debug('Boost library directory is', mlog.bold(self.libdir))
    if self.is_found:
        self.log_success()
    else:
        self.log_fail()

