def update_snapshot(self, data: bytes):
    if self.timestamp is None:
        raise RuntimeError('Cannot update snapshot before timestamp')
    if self.targets is not None:
        raise RuntimeError('Cannot update snapshot after targets')
    logger.debug('Updating snapshot')
    meta = self.timestamp.signed.meta['snapshot.json']
    hashes = meta.hashes or {}
    for (algo, stored_hash) in hashes.items():
        digest_object = sslib_hash.digest(algo)
        digest_object.update(data)
        observed_hash = digest_object.hexdigest()
        if observed_hash != stored_hash:
            raise exceptions.BadHashError(stored_hash, observed_hash)
    try:
        new_snapshot = Metadata.from_bytes(data)
    except DeserializationError as e:
        raise exceptions.RepositoryError('Failed to load snapshot') from e
    if new_snapshot.signed.type != 'snapshot':
        raise exceptions.RepositoryError(f"Expected 'snapshot', got '{new_snapshot.signed.type}'")
    if not verify_with_threshold(self.root, 'snapshot', new_snapshot):
        raise exceptions.UnsignedMetadataError('New snapshot is not signed by root', new_snapshot.signed)
    if new_snapshot.signed.version != self.timestamp.signed.meta['snapshot.json'].version:
        raise exceptions.BadVersionNumberError(f"Expected snapshot version {self.timestamp.signed.meta['snapshot.json'].version}, got {new_snapshot.signed.version}")
    if self.snapshot is not None:
        for (filename, fileinfo) in self.snapshot.signed.meta.items():
            new_fileinfo = new_snapshot.signed.meta.get(filename)
            if new_fileinfo is None:
                raise exceptions.RepositoryError(f"New snapshot is missing info for '{filename}'")
            if new_fileinfo.version < fileinfo.version:
                raise exceptions.BadVersionNumberError(f'Expected {filename} version {new_fileinfo.version}, got {fileinfo.version}.')
    if new_snapshot.signed.is_expired(self.reference_time):
        raise exceptions.ExpiredMetadataError('New snapshot is expired')
    self._trusted_set['snapshot'] = new_snapshot
    logger.debug('Updated snapshot')

def post_exec(self):
    if self.compiled.isinsert:
        if self.IINSERT:
            table_name = self.compiled.statement.table.fullname
            quoted_table_name = f'[{table_name}]'
            self.cursor.execute(f'SET IDENTITY_INSERT {quoted_table_name} OFF')
            self.IINSERT = False
        elif self.HASIDENT:
            if not len(self._last_inserted_ids) or self._last_inserted_ids[0] is None:
                if self.dialect.use_scope_identity:
                    self.cursor.execute('SELECT scope_identity() AS lastrowid')
                else:
                    self.cursor.execute('SELECT @@identity AS lastrowid')
                row = self.cursor.fetchone()
                self._last_inserted_ids = [int(row[0])] + self._last_inserted_ids[1:]
        self.HASIDENT = False
    super(MSSQLExecutionContext, self).post_exec()

def malloc_varsize(self, typeid, length, size, itemsize, offset_to_length, can_collect):
    if can_collect and self.bytes_malloced > self.bytes_malloced_threshold:
        self.collect()
    try:
        varsize = rarithmetic.ovfcheck(itemsize * length)
    except OverflowError:
        raise MemoryError
    size_gc_header = self.gcheaderbuilder.size_gc_header
    try:
        size = rarithmetic.ovfcheck(size + varsize)
    except OverflowError:
        raise MemoryError
    result = raw_malloc(size_gc_header + size)
    (result + size_gc_header + offset_to_length).signed[0] = length
    hdr = llmemory.cast_adr_to_ptr(result, self.HDRPTR)
    hdr.typeid = typeid << 1
    if not self.getfinalizer(typeid):
        hdr.next = self.malloced_objects
        self.malloced_objects = hdr
    else:
        hdr.next = self.malloced_objects_with_finalizer
        self.malloced_objects_with_finalizer = hdr
    self.bytes_malloced += raw_malloc_usage(size + size_gc_header)
    result += size_gc_header
    return llmemory.cast_adr_to_ptr(result, llmemory.GCREF)

def get_execution_sequence(self):
    condensed_graph = self.__create_condensed_graph()
    execution_sequence = []
    while True:
        leaves = self.__get_leaves(condensed_graph)
        if not leaves:
            break
        parallel_tasks = [tuple(cast('list[BaseDiscipline]', condensed_graph.nodes[node_id]['members'])) for node_id in leaves]
        execution_sequence.append(parallel_tasks)
        condensed_graph.remove_nodes_from(leaves)
    return list(reversed(execution_sequence))

def create_or_update_translation(self, locale):
    original = self.as_instance()
    created = False
    try:
        translation = self.object.get_instance(locale)
    except models.ObjectDoesNotExist:
        translation = original.copy_for_translation(locale)
        created = True
    for field in self.synchronized_fields:
        setattr(translation, field, getattr(original, field))
    segment_locations = SegmentLocation.objects.filter(revision=self).annotate_translation(locale.language)
    template_locations = TemplateLocation.objects.filter(revision=self).select_related('template')
    related_object_locations = RelatedObjectLocation.objects.filter(revision=self).select_related('object')
    segments = []
    for location in segment_locations:
        if not location.translation:
            raise MissingTranslationError(location, locale)
        segment = SegmentValue.from_html(location.path, location.translation).with_order(location.order)
        if location.html_attrs:
            segment.replace_html_attrs(json.loads(location.html_attrs))
        segments.append(segment)
    for location in template_locations:
        template = location.template
        segment = TemplateValue(location.path, template.template_format, template.template, template.segment_count, order=location.order)
        segments.append(segment)
    for location in related_object_locations:
        if not location.object.has_translation(locale):
            raise MissingRelatedObjectError(location, locale)
        segment = RelatedObjectValue(location.path, location.object.content_type, location.object.translation_key, order=location.order)
        segments.append(segment)
    ingest_segments(original, translation, self.locale, locale, segments)
    if isinstance(translation, Page):
        translation.slug = slugify(translation.slug)
        translation.save()
        page_revision = translation.save_revision()
        page_revision.publish()
    else:
        translation.save()
        page_revision = None
    TranslationLog.objects.create(revision=self, locale=locale, page_revision=page_revision)
    return (translation, created)

def _pdf_pageinfo_sync_init(infile: Path, pdfminer_loglevel):
    global worker_pdf
    pikepdf_enable_mmap()
    logging.getLogger('pdfminer').setLevel(pdfminer_loglevel)

    class WorkerPDFContext:

        def __init__(self, path):
            self.path = path
            self.pdf = None

        def __enter__(self):
            self.pdf = pikepdf.open(self.path)
            return self.pdf

        def __exit__(self, exc_type, exc_val, exc_tb):
            if self.pdf is not None:
                self.pdf.close()
    worker_pdf = WorkerPDFContext(infile).__enter__()

def _pdf_pageinfo_sync_init(infile: Path, pdfminer_loglevel):
    global worker_pdf
    pikepdf_enable_mmap()
    logging.getLogger('pdfminer').setLevel(pdfminer_loglevel)
    if 'threading' in sys.modules:
        if worker_pdf:
            worker_pdf.close()
    worker_pdf = pikepdf.open(infile)

def on_prepare(self):
    if not self.settings['data']:
        self.settings['data'] = 'io.github.Pithos-tray-symbolic'
    self.preferences_dialog = NotificationIconPluginPrefsDialog(self.window, self.settings)

    def on_settings_changed(settings, key):
        if key == 'data' and self.statusnotifieritem:
            self.statusnotifieritem.set_icon_name(settings[key])
    self.settings.connect('changed', on_settings_changed)

    def on_proxy_ready(obj, result, user_data=None):
        try:
            self.proxy = obj.new_finish(result)
        except GLib.Error as e:
            self.prepare_complete(error='Failed to connect to StatusNotifierWatcher {}'.format(e))
        else:
            logging.info('Connected to StatusNotifierWatcher')
            self.statusnotifieritem = PithosStatusNotifierItem(self.window, connection=self.proxy.get_connection())
            self.prepare_complete()

    def on_watcher_appeared(conn, name, name_owner, user_data=None):
        logging.info('StatusNotifierWatcher appeared')
        self.registered = True

    def on_watcher_disappear(conn, name, user_data=None):
        logging.info('StatusNotifierWatcher disappeared')
        self.registered = False
        self._show_window()
    Gio.bus_watch_name_on_connection(self.bus, STATUS_NOTIFIER_WATCH_NAME, Gio.BusNameWatcherFlags.AUTO_START, on_watcher_appeared, on_watcher_disappear)
    Gio.DBusProxy.new(self.bus, Gio.DBusProxyFlags.DO_NOT_LOAD_PROPERTIES | Gio.DBusProxyFlags.DO_NOT_CONNECT_SIGNALS, None, 'org.kde.StatusNotifierWatcher', '/StatusNotifierWatcher', 'org.kde.StatusNotifierWatcher', None, on_proxy_ready, None)

def process_results(self, doc, results):
    evaluation = {}
    for metric in results:
        evaluation[metric] = results[metric]
    return evaluation

def process_results(self, doc, results):
    metrics = {}
    for (metric_name, metric_value) in results.items():
        metrics[metric_name] = metric_value.get(doc['id'], 0)
    return metrics

