def heartbeat(self, context, node_id, callback_url, agent_version=None):
    LOG.debug('RPC heartbeat called for node %s', node_id)
    if agent_version is None:
        agent_version = '3.0.0'

    def heartbeat_with_deprecation(task, callback_url, agent_version):
        global _SEEN_AGENT_VERSION_DEPRECATIONS
        task.driver.deploy.heartbeat(task, callback_url, agent_version)
    with task_manager.acquire(context, node_id, shared=True, purpose='heartbeat') as task:
        task.spawn_after(self._spawn_worker, heartbeat_with_deprecation, task, callback_url, agent_version)

def parse_trade(self, trade, market=None):
    timestamp = None
    if 'Timestamp' in trade:
        timestamp = trade['Timestamp'] * 1000
    elif 'TimeStamp' in trade:
        timestamp = self.parse8601(trade['TimeStamp'])
    price = None
    cost = None
    if 'Price' in trade:
        price = trade['Price']
    elif 'Rate' in trade:
        price = trade['Rate']
    fee = None
    if 'Fee' in trade:
        fee = {'cost': trade['Fee'], 'currency': market['feeCurrency'] if 'feeCurrency' in market else None}
    elif 'FeeAmount' in trade:
        fee = {'cost': trade['FeeAmount'], 'currency': market['feeCurrency'] if 'feeCurrency' in market else None}
    return {'id': None, 'info': trade, 'timestamp': timestamp, 'datetime': self.iso8601(timestamp), 'symbol': market['symbol'], 'type': None, 'side': trade['Type'].lower(), 'price': price, 'cost': cost, 'amount': trade['Amount'], 'fee': fee}

def is_equivalent_to(self, other):
    if self.file_path != other.file_path:
        return False
    with open(self.input_file, 'r') as f1, open(other.input_file, 'r') as f2:
        return f1.read() == f2.read()

def is_equivalent_to(self, other):
    if self.file_path != other.file_path:
        try:
            with open(self.file_path, 'rb') as f1, open(other.file_path, 'rb') as f2:
                content1 = f1.read()
                content2 = f2.read()
                return content1 == content2
        except IOError:
            return False
    else:
        return True

def _GenerateGradleFile(entry, generator, build_vars, jinja_processor):
    deps_info = entry.DepsInfo()
    gradle = entry.Gradle()
    variables = {'sourceSetName': 'main', 'depCompileName': 'compile'}
    if deps_info['type'] == 'android_apk':
        target_type = 'android_apk'
    elif deps_info['type'] == 'java_library':
        if deps_info['is_prebuilt'] or deps_info['gradle_treat_as_prebuilt']:
            return None
        elif deps_info['requires_android']:
            target_type = 'android_library'
        else:
            target_type = 'java_library'
    elif deps_info['type'] == 'java_binary':
        if gradle['main_class'] == 'org.chromium.testing.local.JunitTestMain':
            target_type = 'android_junit'
            variables['sourceSetName'] = 'test'
            variables['depCompileName'] = 'testCompile'
        else:
            target_type = 'java_binary'
            variables['main_class'] = gradle['main_class']
    else:
        return None
    variables['target_name'] = os.path.splitext(deps_info['name'])[0]
    variables['template_type'] = target_type
    variables['use_gradle_process_resources'] = generator.use_gradle_process_resources
    source_properties = _ReadPropertiesFile(_RebasePath(os.path.join(build_vars['android_sdk_build_tools'], 'source.properties')))
    variables['build_tools_version'] = source_properties['Pkg.Revision']
    variables['compile_sdk_version'] = 'android-%s' % build_vars['android_sdk_version']
    variables['main'] = generator.Generate(entry)
    bootclasspath = gradle.get('bootclasspath')
    if bootclasspath:
        variables['bootclasspath'] = _RebasePath(bootclasspath)
    if entry.android_test_entry:
        variables['android_test'] = generator.Generate(entry.android_test_entry)
        for (key, value) in variables['android_test'].iteritems():
            if isinstance(value, list):
                variables['android_test'][key] = list(set(value) - set(variables['main'][key]))
    return jinja_processor.Render(_TemplatePath(target_type.split('_')[0]), variables)

def add_team_to_topic(user, topic_id):
    data_json = flask.request.json
    check_json_is_valid(create_topic_schema, data_json)
    team_id = data_json.get('team_id')
    topic = v1_utils.verify_existence_and_get(topic_id, _TABLE)
    team_id = v1_utils.verify_existence_and_get(team_id, models.TEAMS, get_id=True)
    if user.is_not_super_admin() and user.is_not_epm():
        raise dci_exc.Unauthorized()
    values = {'topic_id': topic['id'], 'team_id': team_id}
    query = models.JOINS_TOPICS_TEAMS.insert().values(**values)
    try:
        flask.g.db_conn.execute(query)
    except sa_exc.IntegrityError:
        raise dci_exc.DCICreationConflict(models.JOINS_TOPICS_TEAMS.name, 'team_id, topic_id')
    result = json.dumps(values)
    return flask.Response(result, 201, content_type='application/json')

def k8s_install_kubelogin(cmd, client_version='latest', install_location=None, source_url=None):
    cloud_name = cmd.cli_ctx.cloud.name
    if not source_url:
        source_url = 'https://github.com/Azure/kubelogin/releases/download'
        if cloud_name.lower() == 'azurechinacloud':
            source_url = 'https://mirror.azure.cn/kubernetes/kubelogin'
    if client_version == 'latest':
        context = _ssl_context()
        latest_release_url = 'https://api.github.com/repos/Azure/kubelogin/releases/latest'
        if cloud_name.lower() == 'azurechinacloud':
            latest_release_url = 'https://mirror.azure.cn/kubernetes/kubelogin/latest'
        latest_release = urlopen(latest_release_url, context=context).read()
        client_version = json.loads(latest_release)['tag_name'].strip()
    else:
        client_version = "v%s" % client_version
    base_url = source_url + '/{}/kubelogin.zip'
    file_url = base_url.format(client_version)
    install_dir, cli = os.path.dirname(
        install_location), os.path.basename(install_location)
    if not os.path.exists(install_dir):
        os.makedirs(install_dir)
    system = platform.system()
    if system == 'Windows':
        sub_dir, binary_name = 'windows_amd64', 'kubelogin.exe'
    elif system == 'Linux':
        if platform.machine() == 'arm64':
            sub_dir, binary_name = 'linux_arm64', 'kubelogin'
        else:
            sub_dir, binary_name = 'linux_amd64', 'kubelogin'
    elif system == 'Darwin':
        if platform.machine() == 'arm64':
            sub_dir, binary_name = 'darwin_arm64', 'kubelogin'
        else:
            sub_dir, binary_name = 'darwin_amd64', 'kubelogin'
    else:
        raise CLIError(
            'Proxy server ({}) does not exist on the cluster.'.format(system))
    with tempfile.TemporaryDirectory() as tmp_dir:
        try:
            download_path = os.path.join(tmp_dir, 'kubelogin.zip')
            logger.warning('Downloading client to "%s" from "%s",
                           download_path, file_url)
            _urlretrieve(file_url, download_path)
        except IOError as ex:
            raise CLIError(
                'Connection error while attempting to download client ({})'.format(ex))
        _unzip(download_path, tmp_dir)
        download_path = os.path.join(tmp_dir, 'bin', sub_dir, binary_name)
        shutil.move(download_path, install_location)
    os.chmod(install_location, os.stat(install_location).st_mode |
             stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    if system == 'Windows':
        env_paths = os.environ['PATH'].split(';')
        found = next((x for x in env_paths if x.lower().rstrip(
            '\') == install_dir.lower()), None)
        if not found:
            logger.warning('Please add "{0}" to your search PATH so the `{1}` can be found. 2 options: \n'
                           '    1. Run "set PATH=%PATH%;{0}" or "$env:path += '{0}'" for PowerShell. '
                           'This is good for the current command session.\n'
                           '    2. Update system PATH environment variable by following '
                           '"Control Panel->System->Advanced->Environment Variables", and re-open the command window. '
                           'You only need to do it once'.format(install_dir, cli))
    else:
        logger.warning('Please ensure that %s is in your search PATH, so the `%s` command can be found.',
                       install_dir, cli)

def changes_between(model_type: Literal['FeatureFlag', 'Person', 'Insight'], previous: Optional[models.Model], current: Optional[models.Model]) -> List[Change]:
    changes: List[Change] = []
    if previous is None and current is None:
        return changes
    if previous is not None:
        fields = current._meta.fields if current is not None else []
        filtered_fields = [f.name for f in fields if f.name not in field_exclusions[model_type]] + ['tags']
        for field in filtered_fields:
            left = getattr(previous, field, None)
            right = getattr(current, field, None)
            if left is None and right is not None:
                changes.append(Change(type=model_type, field=field, action='created', after=right))
            elif right is None and left is not None:
                changes.append(Change(type=model_type, field=field, action='deleted', before=left))
            elif left != right:
                changes.append(Change(type=model_type, field=field, action='changed', before=left, after=right))
    return changes

def feed_group(self, group: list, status_: str) -> None:
    ration_prey = get_clan_setting('ration_prey')
    for cat in group:
        feeding_amount = PREY_REQUIREMENT[status_]
        needed_amount = feeding_amount
        if cat.is_ill() or cat.is_injured():
            feeding_amount += CONDITION_INCREASE
            needed_amount = feeding_amount
        elif ration_prey and status_ == 'warrior':
            feeding_amount = feeding_amount / 2
        lot_more_prey = self.amount_food_needed() < self.total_amount * 1.5
        if lot_more_prey and self.nutrition_info[cat.ID].percentage < 100:
            feeding_amount += 1
        self.feed_cat(cat, feeding_amount, needed_amount)

def cache_gas_used_for_computation(contract, computation):
    profile = contract.line_profile(computation)
    env = contract.env
    contract_name = contract.compiler_data.contract_name
    sum_net_gas = sum([i.net_gas for i in profile.profile.values()])
    sum_net_tot_gas = sum([i.net_tot_gas for i in profile.profile.values()])
    try:
        fn_name = contract._get_fn_from_computation(computation).name
    except AttributeError:
        fn_name = 'unnamed'
    fn = ContractMethodInfo(contract_name=contract_name, address=to_checksum_address(contract.address), fn_name=fn_name)
    env._cached_call_profiles.setdefault(fn, CallGasStats()).merge_gas_data(sum_net_gas, sum_net_tot_gas)
    s = env._profiled_contracts.setdefault(fn.address, [])
    if fn not in env._profiled_contracts[fn.address]:
        s.append(fn)
    line_profile = profile.get_line_data()
    for (line, gas_used) in line_profile.items():
        env._cached_line_profiles.setdefault(line, []).append(gas_used)
    for _computation in computation.children:
        child_contract = env.lookup_contract(_computation.msg.code_address)
        if child_contract is not None:
            cache_gas_used_for_computation(child_contract, _computation)

