from typing import Optional

def lookup_class(kind: str, apiVersion: Optional[str]=None, default: Optional[object]=None) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className)
    except ImportError:
        klass = None
    if klass:
        register_class(className, klass)
    return klass

def good_friday_unless_christmas_nye_friday(dt):
    if isinstance(dt, pd.DataFrame) or isinstance(dt, pd.Series):
        year = dt.dt.year
    else:
        year = dt.year
    christmas_weekday = Christmas.observance(pd.Timestamp(year, 12, 25)).weekday()
    nyd_weekday = USNewYearsDay.observance(pd.Timestamp(year, 1, 1)).weekday()
    if christmas_weekday != 4 and nyd_weekday != 4:
        return GoodFriday._apply_rule(dt)
    else:
        return pd.NaT

def __init__(self, options=None, register_classes=()):
    self.logger.debug('Creating %s arch', self.name)
    self.option_settings = {o: False for o in self.option_names}
    if options:
        assert isinstance(options, tuple)
        for option_name in options:
            assert option_name in self.option_names
            self.option_settings[option_name] = True
    self.register_classes = register_classes
    self.byte_sizes = {}
    self.byte_sizes['int'] = 4
    self.byte_sizes['ptr'] = 4
    self.byte_sizes['byte'] = 1
    self.byte_sizes['u8'] = 1
    self.FrameClass = Frame

