def execute(self, context):
    obj_list = context.selected_objects
    if not obj_list:
        self.report({'ERROR'}, 'No objects selected')
        return {'CANCELLED'}
    mat_list = util.materialsFromObj(obj_list)
    if not mat_list:
        self.report({'ERROR'}, 'No materials found on selected objects')
        return {'CANCELLED'}
    engine = context.scene.render.engine
    count = 0
    for mat in mat_list:
        if mat.library:
            self.report({'WARNING'}, f'Skipping linked material: {mat.name}')
            continue
        passes = generate.get_textures(mat)
        if not self.useExtraMaps:
            for pass_name in passes:
                if pass_name != 'diffuse':
                    passes[pass_name] = None
            if self.autoFindMissingTextures:
                for pass_name in passes:
                    res = generate.replace_missing_texture(passes[pass_name])
                    if res > 0:
                        mat['texture_swapped'] = True
            if engine == 'BLENDER_RENDER' or engine == 'BLENDER_GAME':
                res = generate.matprep_internal(mat, passes, self.useReflections, self.makeSolid)
                if res == 0:
                    count += 1
                if self.animateTextures:
                    sequences.animate_single_material(mat, context.scene.render.engine)
            elif engine == 'CYCLES' or engine == 'BLENDER_EEVEE':
                res = generate.matprep_cycles(mat, passes, self.useReflections, self.usePrincipledShader, self.makeSolid)
                if res == 0:
                    count += 1
                if self.animateTextures:
                    sequences.animate_single_material(mat, context.scene.render.engine)
            else:
                self.report({'ERROR'}, 'Only blender internal or cycles supported')
                return {'CANCELLED'}
    if self.combineMaterials is True:
        bpy.ops.mcprep.combine_materials(selection_only=True, skipUsage=True)
    if self.improveUiSettings:
        bpy.ops.mcprep.improve_ui()
    self.report({'INFO'}, 'Modified ' + str(count) + ' materials')
    self.track_param = context.scene.render.engine
    self.track_exporter = generate.detect_form(mat_list)
    return {'FINISHED'}

def get_metric(name):
    try:
        return METRIC_REGISTRY[name]
    except KeyError:
        eval_logger.warning(f"Could not find registered metric '{name}' in lm-eval, searching in HF Evaluate library...")
        try:
            metric_object = evaluate.load(name)
            return metric_object.compute
        except Exception:
            eval_logger.error('{} not found in the evaluate library!'.format(name), 'Please check https://huggingface.co/evaluate-metric')

def add_image(self, can_remove=True):

    class ImageSettings(object):

        def __init__(self, images):
            self.key = uuid.uuid4()
            self.image_name = cps.SettingGroup('Select the input image', 'None')
            if can_remove:

                def remove(images=images, key=self.key):
                    index = [x.key for x in images].index(key)
                    del images[index]
                self.remove_button = cps.DoSomething('Remove above image', 'Remove', remove)

        def settings(self):
            return [self.image_name]

        def visible_settings(self):
            if can_remove:
                return [self.image_name, self.remove_button]
            else:
                return [self.image_name]
    self.images.append(ImageSettings(self.images))

